int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, A, B;
    cin >> N >> A >> B;

    long long g = std::gcd(A, B);
    long long a = A / g;
    long long b = B / g;

    // If A+B > N+g, then no overlap structure can create all mixed patterns.
    // In this case, reachable strings are exactly:
    // - all 0
    // - all 1
    // - one contiguous block of 1s of length multiple of g obtainable by one B-op
    //   possibly shrunk/expanded by A/B interactions, which gives lengths:
    //   B, B+g, ..., N-A
    // - symmetrically, one contiguous block of 0s inside all 1s:
    //   A, A+g, ..., N-B
    //
    // Counting distinct strings simplifies to:
    // 2 + max(0, floor((N-A-B)/g)+1) + max(0, floor((N-A-B)/g)+1)
    // = 2 + 2*t, where t = max(0, floor((N-A-B)/g)+1)
    //
    // If A+B <= N+g, then every string constant on each residue class mod g is reachable.
    // There are 2^g such strings.
    //
    // This is the known characterization for this problem.

    if (A + B <= N + g) {
        long long ans = 1, base = 2, exp = g;
        while (exp > 0) {
            if (exp & 1) ans = ans * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        cout << ans % MOD << '\n';
    } else {
        long long t = 0;
        if (N >= A + B) t = (N - A - B) / g + 1;
        long long ans = (2 + 2 * (t % MOD)) % MOD;
        cout << ans << '\n';
    }

    return 0;
}

