        int N = sc.nextInt(), A = sc.nextInt(), B = sc.nextInt();
        // DP: count strings where each 1-run >= B, each internal 0-gap >= A
        // dp[i][last] where last=0 means last char was 0, last=1 means last char was 1
        long[] dp = new long[N+1]; // dp[i] = ways to fill first i chars ending considerations
        // Use segment approach
        long[] f = new long[N+1]; // f[i] = number of valid strings of length i
        f[0] = 1;
        for(int i=1;i<=N;i++){
            // end with 0-run of length g (1<=g, either g>=A or i==g meaning prefix)
            // preceded by nothing (i==g) or a 1-run
            for(int g=1;g<=i;g++){
                if(g<A && g<i) continue; // internal 0-gap must be >=A
                int rem=i-g;
                if(rem==0){f[i]=(f[i]+1)%MOD;break;}// all zeros prefix... 
                // rem must end with a 1-run of length b>=B
                for(int b=B;b<=rem;b++){
                    f[i]=(f[i]+f[rem-b])%MOD;
                }
            }
        }
        // answer = f[N] but we need to handle the all-zeros string
        System.out.println(f[N]);
    }
